    "net.fed.odd": "⚠ Mixed builds · {n} peer(s)",
    "net.fed.odd.tip": "Local {mine}; peers {peers}. An identical rule fingerprint is not identical validation — when a judgement inside one family changed (this round: dust rounds follow the height that includes the record) both sides still fork. Use one build everywhere.",
    "about.net": "Federation demo: open a second wallet window on the same Mac (or another device on the same Wi-Fi). Nodes find each other via mDNS, relay transactions and blocks over gossipsub, elect the block producer with VRF tickets, and converge to one identical ledger.",

