    "world.map.note": "The world map is this planet: the bundled 2 MiB global elevation grid divides the Earth into 2,097,152 parcels of about 19.6 km, 615,081 of them land — that is the real number of shares a coin can be dealt. The seat comes from address ⊕ genesis hash: one address, one cell, forever, no re-rolls. Terrain is generated on this machine; the chain stores only coordinates and ownership and the wallet downloads no map. Hashing guarantees you cannot re-roll, not that you are unique: past ~1000 wallets a collision is likelier than not, so exclusivity needs an on-chain register.",
