    "nav.world": "🌍 Мир",
    "world.map": "Карта мира",
    "world.map.tag": "Вся планета · локальный детерминизм",
    "world.map.note": "Карта мира — это Земля: идущая в комплекте сетка высот (2 МиБ) делит планету на 2 097 152 участка по ≈19,6 км, из них 615 081 на суше — это и есть «доли», которые можно выдать монете. Место считается из адреса ⊕ хеша генезиса: один адрес — одна клетка навсегда, переброс невозможен. Рельеф считается на этом устройстве, цепь хранит только координаты и владельца, кошелёк не качает карту. Хеш запрещает переброс, но не уникальность: после ~1000 кошельков вероятность коллизии переваливает за половину, поэтому эксклюзивность требует записи в цепи.",
