    "net.fed.warn.tip": "Local {mine}; pares {peers}. Distintas familias de reglas significan que ningún lado valida los bloques del otro: pasada la altura de activación cada uno mina su cadena sin avisar (horquilla silenciosa). Unifiquen la versión publicada.",
