    "net.fed.odd.tip": "Local {mine}; pares {peers}. La misma huella de reglas no implica la misma validación: si cambió un criterio dentro de una familia (esta ronda: la ronda de polvo sigue la altura del bloque que lo incluye) también hay horquilla. Usen una única versión publicada.",
    "about.net": "Demo de federación: abre una segunda ventana de la billetera en el mismo Mac (o en otro equipo de la misma red Wi-Fi). Los nodos se descubren por mDNS, retransmiten transacciones y bloques por gossipsub, eligen al productor del bloque con boletos VRF y todos los libros coinciden.",

    "nav.world": "🌍 Mundo",
    "world.map": "Mapa del mundo",
    "world.map.tag": "Todo el planeta · render local determinista",
    "world.map.note": "El mapa del mundo es este planeta: la malla global de elevación de 2 MiB incluida divide la Tierra en 2.097.152 parcelas de ≈19,6 km, 615.081 de ellas en tierra — esos son los repartos que puede recibir una moneda. El asiento sale de dirección ⊕ hash de génesis: una dirección, una casilla para siempre, sin volver a tirar. El terreno se calcula en esta máquina; la cadena solo guarda coordenadas y propiedad y la cartera no descarga mapas. El hash impide repetir el sorteo, no garantiza unicidad: a partir de ~1000 monederos la colisión supera el 50 %, así que la exclusividad exige un registro en la cadena.",
    "world.seat.parcel": "Tu parcela del asiento",
    "world.seat.parcel.tag": "8,96 km · calculada localmente",
    "world.parcel": "Suelo bajo los pies",
    "world.parcel.tag": "256×256 casillas · colocable",
    "world.walk.note": "Este es el suelo que realmente se pisa: la cadena registra (x, z, capa) y el terreno se recalcula desde el hash de génesis más el VRF de cada bloque. La parcela del asiento de arriba sale de dirección ⊕ hash de génesis y todavía no se superpone. Que el asiento tome este suelo es un cambio de consenso (la capa superficial decide la validez de DIG y entity_root), es decir una bifurcación, no cambiar una textura.",
