    "nav.about": "ⓘ À propos",
    "about.title": "À propos de QLight Wallet",
    "about.ver": "Version {v} · Réseau local de démonstration QLight (regtest)",
    "about.intro": "Premier portefeuille de bureau pour le système post-quantique de droits QLight QLX. Clés, signatures et chiffrement se font intégralement sur cet appareil, sans dépositaire.",
    "about.howto": "Commencer en 3 étapes",
    "about.s1t": "① D'abord la sauvegarde",
    "about.s1": "Cliquez « Sauvegarder » dans la barre latérale et conservez le fichier .dat en lieu sûr.",
    "about.s2t": "② Recevoir",
    "about.s2": "Montrez le QR ou partagez votre adresse ql1 — n'importe qui peut vous payer.",
    "about.s3t": "③ Envoyer",
    "about.s3": "Saisissez l'adresse ql1 du destinataire et le montant. Frais 0.001 QLX ; inclusion au prochain bloc.",
    "about.safe": "Consignes de sécurité",
    "about.safe1": "Un mot de passe perdu est irrécupérable — c'est votre seule entrée. Notez-le sur papier, à part.",
    "about.safe2": "Le fichier .dat est la graine chiffrée : conservez le fichier ET le mot de passe.",
    "about.safe3": "regtest est une chaîne de démonstration : les valeurs ne sont pas des actifs réels.",
    "about.audit": "Registre local auditable",
    "about.auditline": "Un bloc toutes les 2 s ; le hachage du bloc lie toutes ses transactions. Au démarrage, la chaîne est vérifiée — un registre modifié refuse de s'étendre.",
    "net.solo": "◦ Mode local",
    "net.fed": "🌐 Fédération · {n} nœuds",
    "net.fed.warn": "⚠ Règles divergentes · {n} pair(s)",
    "net.fed.warn.tip": "Local {mine} ; pairs {peers}. Familles de règles différentes : aucun côté ne valide les blocs de l'autre. Au-delà de la hauteur d'activation, chacun mine sa chaîne sans erreur affichée (fourche silencieuse). Mettez tout le monde sur la même build.",
    "net.fed.odd": "⚠ Builds mêlées · {n} pair(s)",
    "net.fed.odd.tip": "Local {mine} ; pairs {peers}. Empreinte identique ne veut pas dire validation identique : si un critère a changé dans la même famille (ce tour : le tour de poussière suit la hauteur du bloc qui l'inclut), la fourche reste possible. Utilisez une seule build.",
    "about.net": "Démo de fédération : ouvrez une seconde fenêtre du portefeuille sur le même Mac (ou un autre appareil du même Wi-Fi). Les nœuds se découvrent par mDNS, relaient transactions et blocs via gossipsub, élisent le producteur du bloc par tickets VRF, et tous les registres concordent.",

    "nav.world": "🌍 Monde",
    "world.map": "Carte du monde",
    "world.map.tag": "La planète entière · rendu local déterministe",
    "world.map.note": "La carte du monde, c'est cette planète : la grille d'altitude mondiale de 2 Mio fournie divise la Terre en 2 097 152 lots d'environ 19,6 km, dont 615 081 sur terre — c'est là le vrai découpage distribuable à une pièce. Le siège se calcule depuis adresse ⊕ hash de genèse : une adresse, une case pour toujours, aucun nouveau tirage. Le terrain est calculé sur cette machine ; la chaîne ne garde que coordonnées et propriété, le portefeuille ne télécharge aucune carte. Le hash empêche de relancer, pas les doublons : vers 1000 portefeuilles la collision dépasse 50 %, donc l'exclusivité demande un registre on-chain.",
    "world.seat.parcel": "La parcelle de votre siège",
    "world.seat.parcel.tag": "8,96 km · calculée localement",
    "world.parcel": "Le sol sous vos pas",
    "world.parcel.tag": "256×256 cases · plaçable",
    "world.walk.note": "C'est bien le sol que l'on parcourt : la chaîne enregistre (x, z, couche) et le terrain est recalculé depuis le hash de genèse plus le VRF de chaque bloc. La parcelle du siège ci-dessus vient d'adresse ⊕ hash de genèse et ne se superpose pas encore. Faire prendre au siège ce sol demande un changement de consensus (la couche de surface conditionne la validité de DIG et entity_root) : c'est une fourche, pas un remplacement de texture.",
