    "world.how.s2": "Sur la page « Monde », cliquez sur « ⛏ Miner la veine de ce tour » : l'app choisit une cellule de veine selon l'humidité et envoie 1 QLX de frais de frappe à l'adresse de combustion (personne ne peut les reprendre).",
