    "nav.about": "ⓘ Über",
    "about.title": "Über QLight Wallet",
    "about.ver": "Version {v} · QLight-lokales Demonet (regtest)",
    "about.intro": "Der erste Desktop-Wallet für das Post-Quantum-Anrechte-System QLight QLX. Schlüssel, Signaturen und Verschlüsselung entstehen vollständig auf diesem Gerät — ohne Verwahrer.",
    "about.howto": "In 3 Schritten starten",
    "about.s1t": "① Zuerst das Backup",
    "about.s1": "Klicken Sie in der Seitenleiste auf „Backup erstellen“ und sichern Sie die .dat-Datei an einem sicheren Ort.",
    "about.s2t": "② Empfangen",
    "about.s2": "Zeigen Sie den QR-Code oder teilen Sie Ihre ql1-Adresse — jeder kann Ihnen zahlen.",
    "about.s3t": "③ Senden",
    "about.s3": "ql1-Adresse des Empfängers und Betrag eingeben. Gebühr 0.001 QLX; Aufnahme im nächsten Block.",
    "about.safe": "Sicherheitshinweise",
    "about.safe1": "Ein verlorenes Passwort ist unwiederbringlich — es ist der einzige Zugang. Notieren Sie es getrennt auf Papier.",
    "about.safe2": "Die .dat-Datei ist der verschlüsselte Seed: Sichern Sie Datei UND Passwort.",
    "about.safe3": "regtest ist eine Demo-Kette — Werte sind keine realen Vermögenswerte.",
    "about.audit": "Auditierbares lokales Hauptbuch",
    "about.auditline": "Blöcke alle 2 s; der Blockhash bindet jede enthaltene Transaktion. Beim Start wird die Hash-Kette geprüft — veränderte Hauptbücher verweigern die Erweiterung.",
    "net.solo": "◦ Lokaler Demo-Modus",
    "net.fed": "🌐 Föderation · {n} Knoten",
    "net.fed.warn": "⚠ Regelkonflikt · {n} Peer(s)",
    "net.fed.warn.tip": "Lokal {mine}; Peers {peers}. Unterschiedliche Regelfamilien heißen: keine Seite validiert die Blöcke der anderen. Oberhalb der Aktivierungshöhe mined jede Seite ihre eigene Kette, ohne Fehler (stille Abspaltung). Alle auf denselben Build bringen.",
    "net.fed.odd": "⚠ Gemischte Builds · {n} Peer(s)",
    "net.fed.odd.tip": "Lokal {mine}; Peers {peers}. Gleicher Regel-Fingerprint bedeutet gleiche Regeln, aber nicht gleiche Prüfung — innerhalb einer Familie geänderte Prüfung (diese Runde: die Staubs-Runde folgt der Höhe des aufnehmenden Blocks) spaltet ebenfalls. Einheitlichen Build verwenden.",
    "about.net": "Föderations-Demo: Öffnen Sie ein zweites Wallet-Fenster auf demselben Mac (oder einem anderen Gerät im selben WLAN). Die Knoten finden sich per mDNS, leiten Transaktionen und Blöcke über gossipsub weiter, wählen den Blockersteller per VRF-Tickets — und alle Hauptbücher stimmen überein.",

    "nav.world": "🌍 Welt",
    "world.map": "Weltkarte",
    "world.map.tag": "Der ganze Planet · lokales deterministisches Rendern",
    "world.map.note": "Die Weltkarte ist dieser Planet: das mitgelieferte 2-MiB-Höhenraster teilt die Erde in 2.097.152 Parzellen von ≈19,6 km, davon 615.081 an Land — das ist die echte Aufteilung, die eine Münze erhalten kann. Der Sitz kommt aus Adresse ⊕ Genesis-Hash: eine Adresse, ein Feld für immer, kein Neu-Würfeln. Das Gelände rechnet dieses Gerät; die Kette speichert nur Koordinaten und Eigentum, die Wallet lädt keine Karte. Der Hash verbietet nur das Neuwürfeln, nicht die Doppelung: ab ~1000 Wallets liegt die Kollisionswahrscheinlichkeit über 50 %, Exklusivität braucht also ein On-Chain-Register.",
    "world.seat.parcel": "Sitz-Parzelle",
    "world.seat.parcel.tag": "8,96 km · lokal berechnet",
    "world.parcel": "Boden unter den Füßen",
    "world.parcel.tag": "256×256 Felder · platzierbar",
    "world.walk.note": "Das ist der tatsächlich begangene Boden: Die Kette führt (x, z, Ebene), das Gelände wird aus Genesis-Hash plus dem VRF aller Blöcke neu gerechnet. Die Sitz-Parzelle oben kommt aus Adresse ⊕ Genesis-Hash und überlappt ihn noch nicht. Den Sitz diesen Boden übernehmen zu lassen ist eine Konsensänderung (die Oberflächenschicht entscheidet über DIG-Gültigkeit und entity_root), also eine Abspaltung — nicht der Tausch einer Textur.",
    "world.earth.parts": "Erde in {n} Parzellen · {land} an Land (1 ≈ 19,6 km)",
