    "world.how.s3": "次のブロックがクレジットを受け入れて初めて、現在のペース枠ぶんの新規発行が残高に入ります。1回の精算は最大1枠（50→10ブロック、創るほど速く）、空ブロックの分は繰り越しません——コインは掘るもので、タイマーで刷るものではない。",
    "world.how.s4": "総量 2.1 億の上限は不変。鉱脈は高さとともに薄くなり、創世マスは有限なので発行は自然に収束。建造はコインで制限されず、コインは世界を証明する。",
    "world.how.vs": "「採掘」ページ = 出塊。「世界採掘」= 世界で実際に鉱石を 1 マス掘り、次のブロックで発行。世界作りは無料、発行するのは採掘。",
