for (const [lang, names] of Object.entries(WORLD_KINDS)) {
  if (!I18N[lang]) continue;
  names.forEach((name, i) => { I18N[lang][`world.kind.${i}`] = name; });
  Object.assign(I18N[lang], WORLD_EXTRA[lang] || {});
  Object.assign(I18N[lang], DUST_I18N[lang] || {});
  Object.assign(I18N[lang], TRADER_I18N[lang] || {});
  Object.assign(I18N[lang], DIG_I18N[lang] || {});
  Object.assign(I18N[lang], SHELL_I18N[lang] || {});
  Object.assign(I18N[lang], ROAM_I18N[lang] || {});
}

function t(key, params = {}) {
  let s = I18N[LANG] && I18N[LANG][key];
  if (s == null) s = I18N.en[key];
  if (s == null) s = I18N["zh-CN"][key];
  if (s == null) s = key;
  for (const [k, v] of Object.entries(params)) {
    s = s.replaceAll(`{${k}}`, v);
  }
  return s;
}

/** 语言菜单（母语名，WIDTH 固定）。发现 applyI18n 被调用即同步选中项 */
function syncLangControl() {
  const sel = document.getElementById("lang-select");
  if (!sel) return;
  if (!sel.options.length) {
    sel.innerHTML = LANGS.map(([code, name]) => `<option value="${code}">${name}</option>`).join("");
  }
  sel.value = LANG;
}

/** 扫描并应用静态词条 */
function applyI18n() {
  // {v} 由 app.js 从后端 app_version 拿到后填；未就绪时先留空，不写死数字
  const rt = { v: window.__QLX_VERSION__ || "" };
  document.querySelectorAll("[data-i18n]").forEach((el) => {
    el.textContent = t(el.dataset.i18n, rt);
  });
  document.querySelectorAll("[data-i18n-ph]").forEach((el) => {
    el.placeholder = t(el.dataset.i18nPh);
  });
  document.querySelectorAll("[data-i18n-title]").forEach((el) => {
    el.title = t(el.dataset.i18nTitle);
  });
  document.documentElement.lang = LANG;
  document.title = t("app.title");
  syncLangControl();
}

/** 切换语言并重写动态区 */
function setLang(lang) {
  if (!I18N[lang]) return;
  LANG = lang;
  localStorage.setItem("qlight.lang", lang);
  applyI18n();
  if (window.refreshAll) window.refreshAll();
}
